import {COURSES,text} from './curriculum-model.js';
import {SOURCES} from './lesson-model.js';
const lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'ko',t=(ko,en)=>lang==='en'?en:ko,$=id=>document.getElementById(id);document.documentElement.lang=lang;
const el=(tag,parent,value)=>{const e=document.createElement(tag);if(value)e.textContent=value;parent.append(e);return e};
$('lab').textContent=t('실험실 열기','Open laboratory');$('lab').href='index.html?lang='+lang;$('records').textContent=t('기록 검토','Review records');$('records').href='teacher.html?lang='+lang;
$('title').textContent=t('힘의 작용 실험실 · 교사 안내','Forces laboratory · teacher guide');$('intro').textContent=t('하나의 실험대에서 초등·중등·고등 과정을 선택합니다. 학년마다 질문, 조작 범위, 측정 단위와 기록을 분리한 L01 통합 기획의 첫 구현입니다.','Choose elementary, middle or high school on a shared workbench. Questions, controls, units and records differ by course. This is the first implementation of the L01 integrated plan.');
$('scope').textContent=t('성취기준에 맞춰 재구성한 가상 탐구 수업입니다. 특정 출판사 지도서의 원차시를 그대로 구현한 것으로 표시하지 않습니다. 공개 지도서 차시 목차와 교육청 수업 예시는 참고했으며, 비공개 교사용 지도서의 본문·평가 문항은 검증하지 못했습니다. 실제 물체 관찰, 구두 설명과 실험으로 보완하세요.','These investigations are adapted to curriculum objectives, not a reproduction of a publisher’s teacher guide. Public lesson outlines and an education-office example informed the route. Restricted guide text and assessment items have not been verified. Supplement with real observations, discussion and experiments.');
el('h2',$('flow'),t('공통 수업 순서','Shared lesson sequence'));const list=el('ol',$('flow'));for(const pair of [
['과정과 실험 선택 → 물체와 바꿀 조건을 확인합니다.','Choose a course and experiment; identify the object and variable.'],
['먼저 예상하기 → 말이나 그림으로 예상합니다. 별도 예상 입력은 강제하지 않습니다.','Predict verbally or with a drawing. Prediction entry is not forced.'],
['한 조건만 바꾸고 측정 → 다시 측정하여 두 기록을 비교합니다.','Change one condition, measure, and repeat for comparison.'],
['실험 기록 펼치기 → 조건과 측정값을 근거로 설명을 작성합니다.','Open the notebook and explain using conditions and measurements.'],
['새 조건에 적용 → 다음 실험이나 생활 사례를 실제 실험으로 확인합니다.','Apply to a new condition or everyday case and check with a real experiment.']])el('li',list,text(pair,lang));
el('p',$('flow'),t('한 실험은 약 8–12분을 권합니다. 초등은 2차시 이상, 중등은 3차시 이상으로 나누세요. 고등은 과목별 1–2차시를 기준으로 실제 수업에서 조정합니다.','Allow about 8–12 minutes per investigation. Split elementary into at least two lessons and middle into at least three. Adjust high-school routes to one or two lessons per subject.'));
for(const [id,c]of Object.entries(COURSES)){el('h2',$('courses'),text(c.label,lang));const link=el('a',$('courses'),t('이 과정으로 열기','Open this course'));link.href='index.html?course='+id+'&lang='+lang;const wrap=el('div',$('courses'));wrap.className='scroll';const table=el('table',wrap),head=el('tr',el('thead',table));for(const label of [t('순서 · 성취기준','Order · standard'),t('내용과 조작','Content and operation'),t('근거로 설명하기','Explain with evidence')])el('th',head,label);const body=el('tbody',table);c.activities.forEach((a,i)=>{const row=el('tr',body);el('td',row,(i+1)+'. '+text(a.title,lang)+' · '+a.codes.join(', '));el('td',row,text(a.instruction,lang));el('td',row,text(a.prompt,lang))});}
el('h2',$('models'),t('모형의 범위와 수치 읽기','Model scope and measurements'));const modelList=el('ul',$('models'));for(const pair of [
['초등: 힘 화살표·벡터·돌림힘 식을 표시하지 않습니다. 저울은 g와 kg를 함께 읽습니다. 도구의 힘은 상대 비교 눈금이며 1칸은 1 kg 물체를 직접 들 때의 힘입니다. 들어 올리는 높이는 0.5 m로 고정합니다. 지레·빗면 원리식을 평가하지 않습니다.','Elementary: no force arrows, vectors or torque equations. Read scales in g and kg. Tool force uses a relative scale: one unit equals directly lifting 1 kg. Lift height stays at 0.5 m. Do not assess mechanisms using equations.'],
['수레: 밀고 당기기와 두 힘의 평형은 마찰 없는 수평면입니다. 중력과 수직항력은 상쇄되어 생략합니다. 1.2 s 동안 측정합니다. 출발 상태를 바꾸어 합력 0이 정지만 뜻하지 않음을 비교합니다.','Cart: push/pull and parallel equilibrium use a frictionless horizontal plane. Gravity and normal force cancel and are omitted. Measure for 1.2 s. Change initial motion to distinguish zero net force from rest.'],
['마찰: 출발 속도 1.5 m/s, 미끄럼 마찰 모형입니다. 수레 모양은 공통 표상이며 바퀴 구름 마찰을 재현하지 않습니다. 정지 후 마찰력을 꺼 역주행을 방지합니다. 안전장치 목표선은 출발점에서 1 m입니다.','Friction: start at 1.5 m/s using sliding friction. The shared cart does not model rolling resistance. Friction ceases at rest to prevent reversal. The design target is 1 m from release.'],
['중력·탄성력: 지구 g=9.8, 달 g=1.62 m/s². 용수철 k=50 또는 100 N/m인 정적 평형이며 진동·한계·히스테리시스는 생략합니다.','Gravity/spring: Earth g=9.8 and Moon g=1.62 m/s². Spring k=50 or 100 N/m, at static equilibrium. Oscillations, limits and hysteresis are omitted.'],
['부력: 질량 1 kg, 잠긴 부피 0–400 cm³, 액체 밀도 1000 또는 1200 kg/m³. 줄로 매단 정적 측정이며 자유 부유 운동이 아닙니다.','Buoyancy: 1 kg, submerged volume 0–400 cm³, density 1000 or 1200 kg/m³. Suspended static measurement, not free floating dynamics.'],
['고등 물리학: 가벼운 막대·받침 하나·오른쪽 하중 10 N. 받침 반력을 포함한 알짜힘은 0이며 돌림힘을 따로 확인합니다. 기울기·넘어짐은 도식 애니메이션이므로 회전 시간·각도 데이터로 사용하지 않습니다.','Physics: massless beam, one support, 10 N right load. Net force includes support reaction and is zero; check torque separately. Tilt/tipping animations are schematic, not angular time-series data.'],
['고등 역학: 벡터 합성은 질량 1 kg인 수평면 물체입니다. 빗면은 질량 1 kg, 아래로 미끄러지기 직전의 극한 마찰 μN을 사용해 최소 장력을 구합니다. 일반적인 정지 마찰을 항상 μN으로 두지 않습니다.','Mechanics: planar vectors use a 1 kg horizontal object. The 1 kg incline case is at impending downward slip, with limiting friction μN and minimum rope tension. General static friction is not assumed always equal to μN.'],
['도구 크기·물 높이·용수철·기울기는 확대 표상입니다. 수치 층이 계산값이며 실측 오차·기구 정밀도는 포함하지 않습니다.','Instrument geometry, fluid levels, extension and inclinations are enlarged schematic representations. Numbers are calculated values; instrument errors and precision are omitted.'],
['기록은 이 브라우저에만 저장됩니다. JSON으로 내려받아 다른 컴퓨터의 기록 검토 화면에서 불러오세요. 자동 점수·합계·등급을 산출하지 않습니다. 교사는 조건 통제·비교 근거·설명·생활 적용을 관찰합니다.','Records remain in this browser. Export JSON and import it in review on another computer. No automatic score, total or grade. Review variable control, evidence, explanation and everyday transfer.']])el('li',modelList,text(pair,lang));
el('h2',$('sources'),t('근거와 출처','Basis and sources'));const sources=el('ul',$('sources'));for(const source of SOURCES){const li=el('li',sources),a=el('a',li,source.title);a.href=source.url;a.target='_blank';a.rel='noopener';el('small',li,' — '+source.locator)}const legacy=el('a',$('sources'),t('이전 중등 6단계 수업 안내','Previous six-stage middle-school lesson'));legacy.href='guide-legacy.html?lang='+lang;
